import java.util.*;
public class NombresUnicos {
    public static void main(String[] args) {
        String[] nombres = {"Ana", "Carlos", "Ana", "Beatriz", "Carlos", "David"};
        Set<String> unicos = new HashSet<>();
        for (String nombre : nombres) {
            unicos.add(nombre);
        }
        System.out.println("Nombres únicos: " + unicos);
    }
}

